import { trimParams } from "./zzfx.js";

const HEADER = `// Sound catalog: ZzFX parameter arrays for every in-game sound effect.
// Generated by the Sound Lab page (sound-showcase.html) - use its export buttons, then
// paste the result over this file. Hand edits are fine; keep one entry per line.
// Param order: volume, randomness, frequency, attack, sustain, release, shape, shapeCurve, slide,
// deltaSlide, pitchJump, pitchJumpTime, repeatTime, noise, modulation, bitCrush, delay,
// sustainVolume, decay, tremolo, filter. Trailing defaults may be omitted.
// cooldown = minimum milliseconds between two plays of the same sound.
`;

function roundParam(value) {
  return Math.round(value * 1000) / 1000;
}

export function formatCatalogEntry(entry) {
  const params = trimParams(entry.params).map(roundParam);
  return (
    `  { id: ${JSON.stringify(entry.id)}, group: ${JSON.stringify(entry.group)}, ` +
    `label: ${JSON.stringify(entry.label)}, cooldown: ${Math.round(entry.cooldown ?? 0)}, ` +
    `params: [${params.join(", ")}] },`
  );
}

export function formatCatalogModule(entries) {
  return `${HEADER}export const SOUND_CATALOG = [\n${entries.map(formatCatalogEntry).join("\n")}\n];\n`;
}

// Tolerant list parser: accepts ZzFX-designer style arrays (".05", "undefined", empty slots).
export function parseNumberList(text) {
  return String(text)
    .split(",")
    .map((token) => {
      const trimmed = token.trim();
      return trimmed === "" || trimmed === "undefined" ? NaN : Number(trimmed);
    });
}

/**
 * Parse text pasted back into the Sound Showcase page. Understands:
 *  - an exported catalog module (one `{ id: "...", ..., params: [...] }` entry per line)
 *  - a JSON object `{ "gunShot": [..], "blink": { "params": [..], "cooldown": 80 } }`
 *  - a bare ZzFX array, e.g. `zzfx(...[1,.05,220])` or `[1,.05,220]` (returned as `single`)
 * Returns { entries: { [id]: { params, cooldown? } }, single: number[] | null }.
 */
export function parseSoundExport(text) {
  const source = String(text ?? "").trim();
  const result = { entries: {}, single: null };
  if (!source) {
    return result;
  }

  const lineRegex = /id:\s*"([^"]+)"[^\n]*?(?:cooldown:\s*(\d+)[^\n]*?)?params:\s*\[([^\]]*)\]/g;
  let match = lineRegex.exec(source);
  while (match) {
    const entry = { params: parseNumberList(match[3]) };
    if (match[2] !== undefined) {
      entry.cooldown = Number(match[2]);
    }
    result.entries[match[1]] = entry;
    match = lineRegex.exec(source);
  }
  if (Object.keys(result.entries).length > 0) {
    return result;
  }

  if (source.startsWith("{")) {
    try {
      const json = JSON.parse(source);
      Object.entries(json).forEach(([id, value]) => {
        if (Array.isArray(value)) {
          result.entries[id] = { params: value.map((entry) => (entry === null ? NaN : Number(entry))) };
        } else if (value && Array.isArray(value.params)) {
          const entry = { params: value.params.map((item) => (item === null ? NaN : Number(item))) };
          if (Number.isFinite(Number(value.cooldown))) {
            entry.cooldown = Number(value.cooldown);
          }
          result.entries[id] = entry;
        }
      });
      return result;
    } catch {
      // fall through to the bare-array form
    }
  }

  const arrayMatch = /\[([^\]]*)\]/.exec(source);
  if (arrayMatch) {
    result.single = parseNumberList(arrayMatch[1]);
  }
  return result;
}
